public class AbstractBankAccountMain { public static void main(String[] args) { BankAccount s=new SavingsAccount(1000), c=new CurrentAccount(1500); s.deposit(250); s.withdraw(100); c.deposit(500); c.withdraw(300); s.displayBalance(); c.displayBalance(); } }
abstract class BankAccount { protected double balance; BankAccount(double balance){this.balance=Math.max(0,balance);} abstract void deposit(double amount); abstract void withdraw(double amount); void displayBalance(){System.out.println(getClass().getSimpleName()+" balance: Rs. "+balance);} }
class SavingsAccount extends BankAccount { SavingsAccount(double b){super(b);} void deposit(double a){if(a>0)balance+=a;} void withdraw(double a){if(a>0&&a<=balance&&balance-a>=100)balance-=a;else System.out.println("Savings withdrawal rejected.");} }
class CurrentAccount extends BankAccount { CurrentAccount(double b){super(b);} void deposit(double a){if(a>0)balance+=a;} void withdraw(double a){if(a>0&&a<=balance)balance-=a;else System.out.println("Current withdrawal rejected.");} }
